// Original CC0 Poly Haven Rock Moss Set 01 / Rock03, by Kless Gyzen.
// Prepared offline by tools/prepare-rock-relief-v1.8.py from the original
// 5,000-triangle mesh. This upper envelope belongs in the shared physical and
// rendered heightfield; it is not a separate decorative collision surface.
export const ROCK_RELIEF = Object.freeze({
  "name": "Rock03 upper-envelope terrain relief",
  "source": "https://polyhaven.com/a/rock_moss_set_01",
  "author": "Kless Gyzen",
  "license": "CC0-1.0",
  "sourceNode": "rock_moss_set_01_rock03",
  "sourceTriangles": 5000,
  "gridSize": 65,
  "gridEncoding": "uint16 little-endian, Z rows / X columns, values divided by 65535",
  "normalizedBounds": [
    -1,
    1
  ],
  "buriedHeightFraction": 0.38,
  "cutoffSourceY": 0.007011703848838813,
  "sampledPeakAboveCutoff": 0.6797830011051649,
  "sourceXZCenter": [
    0.036291658878326416,
    0.016173064708709717
  ],
  "sourceXZHalfExtent": [
    1.054291307926178,
    1.0397928357124329
  ],
  "peak": {
    "x": -0.59375,
    "z": 0.03125,
    "height": 1
  },
  "payloadBytes": 8450,
  "payloadSha256": "dea145bca5249d131708a57a014a7f10afe24c7181fba1d70a59ad74c57a119a"
});
const GRID_SIZE = 65, LAST_CELL = GRID_SIZE - 2, GRID_SCALE = (GRID_SIZE - 1) / 2;
const HEIGHTS = (() => {
  const bytes = Uint8Array.from(atob(''), character => character.charCodeAt(0));
  const heights = new Uint16Array(GRID_SIZE * GRID_SIZE);
  for (let index = 0; index < heights.length; index++) heights[index] = bytes[index * 2] | bytes[index * 2 + 1] << 8;
  return heights;
})();

// x/z are coordinates relative to one outcrop's existing center, rotation and
// radii. The result is continuous, nonnegative and zero at/outside +/-1; its
// maximum is one. Multiply by the existing outcrop peak height exactly once.
export function rockReliefAt(x, z) {
  if (!(x > -1 && x < 1 && z > -1 && z < 1)) return 0;
  const gridX = (x + 1) * GRID_SCALE, gridZ = (z + 1) * GRID_SCALE;
  const ix = Math.min(LAST_CELL, Math.floor(gridX)), iz = Math.min(LAST_CELL, Math.floor(gridZ));
  const tx = gridX - ix, tz = gridZ - iz, index = iz * GRID_SIZE + ix;
  const lower = HEIGHTS[index] + (HEIGHTS[index + 1] - HEIGHTS[index]) * tx;
  const upper = HEIGHTS[index + GRID_SIZE] + (HEIGHTS[index + GRID_SIZE + 1] - HEIGHTS[index + GRID_SIZE]) * tx;
  return (lower + (upper - lower) * tz) / 65535;
}
